const fs   = require('fs');
const path = require('path');

// ── Hardcoded working directory ───────────────────────────────────────────────
const dir = '/Users/ramdudeja/Desktop/bankingexpertram';

// ── Read script.md ────────────────────────────────────────────────────────────
const scriptPath = path.join(dir, 'script.md');
if (!fs.existsSync(scriptPath)) {
  throw new Error(`script.md not found at: ${scriptPath}`);
}
const scriptMd = fs.readFileSync(scriptPath, 'utf8');

// ── Count paragraphs ──────────────────────────────────────────────────────────
const paragraphs     = scriptMd.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);
const paragraphCount = paragraphs.length;
const imagesNeeded   = Math.max(1, paragraphCount - 2);

// ── Extract title & subtitle from first two non-empty lines ───────────────────
const lines    = scriptMd.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const title    = lines[0] ? lines[0].replace(/^(TITLE:|#{1,3})\s*/i, '').trim() : 'Cyber Fraud Alert';
const subtitle = lines[1] ? lines[1].replace(/^(SUBTITLE:|#{1,3})\s*/i, '').trim() : 'Apne aap ko bachao';

// ── Try structured NEWS SUMMARY block first ───────────────────────────────────
let newsText = '';
let stories  = [];

const newsMatch = scriptMd.match(/## NEWS SUMMARY\n([\s\S]*?)\n---/);
if (newsMatch) {
  newsText = newsMatch[1].trim();
  const storyRegex = /NEWS (\d+): (.+?)\n([\s\S]*?)(?=NEWS \d+:|$)/g;
  let match;
  while ((match = storyRegex.exec(newsText)) !== null) {
    stories.push({
      index:    parseInt(match[1]),
      headline: match[2].trim(),
      summary:  match[3].trim().split('\n')[0]
    });
  }
}

// ── Fallback: plain Hindi narrative script ────────────────────────────────────
if (stories.length === 0) {
  newsText = scriptMd.slice(0, 3000);
  stories  = paragraphs.slice(0, imagesNeeded).map((para, i) => ({
    index:    i + 1,
    headline: para.split(/[।.!?]/)[0].trim().slice(0, 80) || `Scene ${i + 1}`,
    summary:  para.slice(0, 200)
  }));
}

// ── Build numbered paragraphs for image prompt generation ─────────────────────
// Skip first para (title line) and last para (outro/CTA) — no images needed
const contentParagraphs  = paragraphs.slice(1, paragraphs.length - 1);
const numberedParagraphs = contentParagraphs
  .slice(0, imagesNeeded)
  .map((para, i) => `PARAGRAPH ${i + 1}:\n${para}`)
  .join('\n\n');

// ── Return ────────────────────────────────────────────────────────────────────
return [{
  json: {
    title,
    subtitle,
    newsText,
    numberedParagraphs,
    stories,
    paragraphCount,
    imagesNeeded,
    scriptPath
  }
}];

