// ── Compression settings ──────────────────────────────────────────────────────
const JPEG_QUALITY = 92;
const MAX_WIDTH    = 1792;
const CONVERT_WEBP = false;

// ── Helper: compress image ────────────────────────────────────────────────────
function compressImage(inputPath, quality, maxWidth, toWebp) {
  const outputPath = toWebp ? inputPath.replace(/\.jpeg$/, '.webp') : inputPath;
  const pyCode = `
from PIL import Image
import sys, os
inp = sys.argv[1]; out = sys.argv[2]; q = int(sys.argv[3]); mw = int(sys.argv[4])
img = Image.open(inp)
if img.width > mw:
    img = img.resize((mw, int(img.height * (mw / img.width))), Image.LANCZOS)
if img.mode in ('RGBA', 'P'): img = img.convert('RGB')
fmt = 'WEBP' if out.endswith('.webp') else 'JPEG'
img.save(out, fmt, quality=q, optimize=True)
before = os.path.getsize(inp); after = os.path.getsize(out)
print(f"{before},{after}")
`;
  const pyPath = path.join(dir, '_compress_tmp.py');
  fs.writeFileSync(pyPath, pyCode, 'utf8');
  let output = '';
  try {
    output = execSync(
      `python3 "${pyPath}" "${inputPath}" "${outputPath}" "${quality}" "${maxWidth}"`,
      { encoding: 'utf8', timeout: 30000 }
    );
  } finally { try { fs.unlinkSync(pyPath); } catch(_) {} }
  if (toWebp && outputPath !== inputPath && fs.existsSync(outputPath)) {
    try { fs.unlinkSync(inputPath); } catch(_) {}
  }
  const [before, after] = output.trim().split(',').map(Number);
  return {
    finalPath:    outputPath,
    beforeKb:     Math.round(before / 1024),
    afterKb:      Math.round(after  / 1024),
    savedKb:      Math.round((before - after) / 1024),
    savedPercent: Math.round((1 - after / before) * 100)
  };
}

// ── Helper: generate image via DALL-E and save ────────────────────────────────
async function generateAndSave(prompt, filepath) {
  const body = JSON.stringify({
    model: 'gpt-image-1', prompt, n: 1,
    size: '1536x1024', quality: 'high'
  });
  const b64Data = await new Promise((resolve, reject) => {
    const req = https.request({
      hostname: 'api.openai.com',
      path: '/v1/images/generations',
      method: 'POST',
      headers: {
        'Content-Type':   'application/json',
        'Authorization':  `Bearer ${apiKey}`,
        'Content-Length': Buffer.byteLength(body)
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          if (parsed.error) reject(new Error('gpt-image-1 error: ' + parsed.error.message));
          else resolve(parsed.data[0].b64_json);
        } catch(e) {
          reject(new Error('gpt-image-1 parse error: ' + data.slice(0, 200)));
        }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });

  fs.writeFileSync(filepath, Buffer.from(b64Data, 'base64'));

  const compression = compressImage(filepath, JPEG_QUALITY, MAX_WIDTH, CONVERT_WEBP);
  console.log(`   📦 ${path.basename(filepath)}: ${compression.beforeKb}KB → ${compression.afterKb}KB (saved ${compression.savedPercent}%)`);
  return compression;
}

